private static String p4RevocationScalarSupport(int producer) throws Exception {
  return """
      import * as revFs from 'node:fs';
      const revStateFile=%s,revFailedFile=%s,revOrigin=%s,revProducer=%d,revLedgerRoot=%s;
      let revCase=0,revSeq=0,revTail=Promise.resolve(),revStarted=false,revNativeOrdinal=0;
      let revPending=0,revOriginalPending=0,revAcked=0,revFailed=false,revSealing=false,revSealed=false;
      let revLocalMode=null,revWatching=false;
      const revActive=new Map(),revGroups=new Set();
      const revMode=()=>{try{return revFs.existsSync(revStateFile)?JSON.parse(revFs.readFileSync(revStateFile,'utf8')):null;}catch{return null;}};
      const revMarker=()=>{try{const fd=revFs.openSync(revFailedFile,
        revFs.constants.O_WRONLY|revFs.constants.O_CREAT|revFs.constants.O_APPEND|revFs.constants.O_NOFOLLOW,0o600);
        try{revFs.writeSync(fd,'1\\n');}finally{revFs.closeSync(fd);}}catch{}};
      const revCheckRoot=()=>{
        const root=revFs.lstatSync(revLedgerRoot);
        if(root.isSymbolicLink()||!root.isDirectory()||revFs.realpathSync(revLedgerRoot)!==revLedgerRoot
          ||(root.mode&0o777)!==0o700||root.uid!==process.getuid())throw new Error('ROOT');
      };
      const revPublish=(mode,sealed)=>{
        try{
          revCheckRoot();
          const target=revLedgerRoot+'/'+mode.case+'-'+revProducer+'.json',tmp=target+'.tmp';
          if(revFs.existsSync(target)){const old=revFs.lstatSync(target);
            if(old.isSymbolicLink()||!old.isFile()||(old.mode&0o777)!==0o600)throw new Error('FILE');}
          const body=JSON.stringify({case:mode.case,producer:revProducer,epoch:mode.epoch,role:revProducer,
            sent:revSeq,acked:revAcked,pending:revPending+revOriginalPending,originalPending:revOriginalPending,
            failed:revFailed,sealed});
          if(Buffer.byteLength(body)>1024)throw new Error('BOUND');
          revCheckRoot();
          const fd=revFs.openSync(tmp,revFs.constants.O_WRONLY|revFs.constants.O_CREAT|revFs.constants.O_EXCL|
            revFs.constants.O_NOFOLLOW,0o600);
          try{revFs.writeFileSync(fd,body);revFs.fsyncSync(fd);}finally{revFs.closeSync(fd);}
          revCheckRoot();
          revFs.renameSync(tmp,target);
        }catch{revFailed=true;revMarker();}
      };
      const revFail=()=>{revFailed=true;revMarker();if(revLocalMode)revPublish(revLocalMode,revSealed);};
      const revMaybeSeal=()=>{
        if(revSealing&&revPending===0&&revOriginalPending===0){revSealed=true;revPublish(revLocalMode,true);}
      };
      const revInit=mode=>{
        if(revCase===mode.case)return;
        if(revLocalMode&&!revSealed){revFail();return;}
        revCase=mode.case;revSeq=0;revPending=0;revAcked=0;revOriginalPending=0;
        revTail=Promise.resolve();revLocalMode=mode;revSealing=false;revSealed=false;
        if(revProducer!==3&&!revWatching){
          revCheckRoot();
          const command=revLedgerRoot+'/'+mode.case+'-'+revProducer+'-seal.json';revWatching=true;
          revFs.watchFile(command,{interval:25,persistent:false},()=>{
            try{revCheckRoot();if(!revFs.existsSync(command))return;
              const stat=revFs.lstatSync(command);
              if(stat.isSymbolicLink()||!stat.isFile()||stat.size>1024||(stat.mode&0o777)!==0o600)
                throw new Error('COMMAND');
              revCheckRoot();
              const seal=JSON.parse(revFs.readFileSync(command,'utf8'));
              if(Object.keys(seal).sort().join(',')!=='case,epoch,producer,seal'||seal.case!==mode.case
                ||seal.epoch!==mode.epoch||seal.producer!==revProducer||seal.seal!==true)throw new Error('EPOCH');
              revSealing=true;revFs.unwatchFile(command);revWatching=false;revMaybeSeal();
            }catch{revFail();revSealing=true;revFs.unwatchFile(command);revWatching=false;revMaybeSeal();}
          });
        }
      };
      const revEmit=(mode,event,ordinal=0,operation=0,reason=0,ok=true,deltaMicros=0)=>{
        if(!mode?.active)return;
        try{revInit(mode);}catch{revFail();return;}
        if(revSealing||revSealed){revFail();return;}
        revPending++;
        const body={case:mode.case,producer:revProducer,seq:++revSeq,event,ordinal,operation,reason,ok,deltaMicros};
        const acknowledgedAt=performance.now();
        revTail=revTail.then(async()=>{
          const response=await fetch(revOrigin+'/p3/revocation-observer',{method:'POST',
            headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(1000)});
          const ack=await response.json();
          if(response.status!==200||Object.keys(ack).sort().join(',')!=='accepted,flipped,seq'
            ||ack.accepted!==true||ack.seq!==body.seq||typeof ack.flipped!=='boolean')throw new Error('OBSERVER');
          revAcked++;
          if(event===4&&ack.flipped)revEmit(mode,8,0,0,0,true,Math.ceil((performance.now()-acknowledgedAt)*1000));
        }).catch(()=>{revFail();}).finally(()=>{
          revPending--;revPublish(mode,revSealed);revMaybeSeal();
        });
      };
      const revRestore=()=>{
        let restored=true;
        for(const group of [...revGroups]){
          for(const [name,descriptor,wrapped] of [...group.methods]){
            const current=Object.getOwnPropertyDescriptor(group.cap,name);
            let success=false;
            try{if(current?.value===wrapped)success=descriptor?
              Reflect.defineProperty(group.cap,name,descriptor):Reflect.deleteProperty(group.cap,name);}catch{}
            if(success)group.methods=group.methods.filter(item=>item[0]!==name);else{restored=false;revFail();}
          }
          if(!group.methods.length){group.cap=null;revGroups.delete(group);}
        }
        return restored;
      };
      const revObserveNative=(cap,mode)=>{
        if(!mode?.active)return;
        if(!cap||revGroups.size||typeof cap.fillPassword!=='function'||typeof cap.invoke!=='function'){revFail();return;}
        const group={cap,methods:[]};revGroups.add(group);
        for(const name of ['fillPassword','invoke']){
          const descriptor=Object.getOwnPropertyDescriptor(cap,name),original=cap[name];
          const wrapped=function(...args){
            const operation=name==='fillPassword'?1:args[0]?.operation?.kind==='click'?2:3;
            const ordinal=++revNativeOrdinal;revActive.set(ordinal,operation);revEmit(mode,2,ordinal,operation);
            const settled=ok=>{revActive.delete(ordinal);revEmit(mode,3,ordinal,operation,0,ok);};
            let result;try{result=Reflect.apply(original,this,args);}catch(error){settled(false);throw error;}
            try{result.then(()=>settled(true),()=>settled(false)).catch(()=>{revFail();});}catch{revFail();}
            return result;
          };
          try{if(!Reflect.defineProperty(cap,name,{...(descriptor??{configurable:true,writable:true,enumerable:true}),value:wrapped}))throw new Error('DESCRIPTOR');
            group.methods.push([name,descriptor,wrapped]);}catch{revFail();}
        }
      };
      """.formatted(JSON.writeValueAsString(TEMP.resolve("p4-revocation-state.json").toString()),
          JSON.writeValueAsString(TEMP.resolve("p4-revocation-observer-failed").toString()),
          JSON.writeValueAsString(ORIGIN), producer,
          JSON.writeValueAsString(TEMP.toRealPath().resolve("p4-revocation-producers").toString()));
}

private static String p4GuidedRevocationObservers() throws Exception {
  String root = Path.of("../studio-runner/dist").toAbsolutePath().normalize().toUri().toString();
  return p4RevocationScalarSupport(1) + """
      import {GuidedRuntime as RevRuntime} from %s;
      import {GuidedOwnership as RevOwnership} from %s;
      const revOwners=new WeakMap(),revRuntimes=new WeakMap();
      const revStart=RevRuntime.prototype.start;
      RevRuntime.prototype.start=function(...args){const result=Reflect.apply(revStart,this,args),mode=revMode();
        if(mode?.active&&mode.path===1){const runtime=this;
          result.then(()=>{try{if(!runtime.accepting||revStarted)throw new Error('OWNER');
            revStarted=true;revRuntimes.set(runtime,mode);revObserveNative(runtime.browser?.observations,mode);
            revEmit(mode,1,1);}catch{revFail();}},()=>{revFail();}).catch(()=>{revFail();});}
        return result;};
      const revCheck=RevOwnership.prototype.checkGrant;
      RevOwnership.prototype.checkGrant=function(...args){const result=Reflect.apply(revCheck,this,args),mode=revMode();
        if(mode?.active&&mode.path===1){try{const entry=args[0];
          if(entry.stopped!==false)throw new Error('OWNER');
          if(args[2]===true)revOwners.set(entry,mode.case);
          else if(revStarted&&revOwners.get(entry)===mode.case)revEmit(mode,4,1);
        }catch{revFail();}}return result;};
      const revInvalidate=RevOwnership.prototype.invalidate;
      RevOwnership.prototype.invalidate=function(...args){const result=Reflect.apply(revInvalidate,this,args),mode=revMode();
        if(mode?.active&&mode.path===1&&revOwners.get(args[0])===mode.case){
          if(args[0].stopped===true)revEmit(mode,5,1);else revFail();}return result;};
      const revStop=RevRuntime.prototype.stop;
      RevRuntime.prototype.stop=function(...args){const mode=revRuntimes.get(this);
        if(mode){const restored=revRestore();revEmit(mode,6,1,0,0,restored);}
        const result=Reflect.apply(revStop,this,args);
        if(mode){const reason=['REVOKED','LEASE_LOST','EXPIRED','CANCELLED','CONTEXT_LOST'].indexOf(args[0])+1;
          if(this.accepting===false&&reason>0)revEmit(mode,5,1,0,reason);else revFail();
          result.then(()=>revEmit(mode,9,1),()=>{revFail();}).catch(()=>{revFail();});revRuntimes.delete(this);}
        return result;};
      """.formatted(JSON.writeValueAsString(root + "guided/runtime.js"),
          JSON.writeValueAsString(root + "guided/ownership.js"));
}

private static String p4OrdinaryRevocationHttp() throws Exception {
  String root = Path.of("../studio-runner/dist").toAbsolutePath().normalize().toUri().toString();
  return p4RevocationScalarSupport(2) + """
      import {createFetchHttpClient as revRealClient} from %s;
      import {validSecretControl as revValidControl,ackRequestsCancel as revRequestsCancel} from %s;
      const revHttp=revRealClient(),revSend=revHttp.send;
      revHttp.send=function(...args){const mode=revMode();
        const selected=mode?.active&&mode.path===2&&args[0]?.method==='GET'
          &&args[0]?.url===mode.controlUrl;
        if(selected){try{revInit(mode);}catch{revFail();}revOriginalPending++;}
        let result;try{result=Reflect.apply(revSend,this,args);}catch(error){
          if(selected){revOriginalPending--;revFail();revPublish(mode,revSealed);revMaybeSeal();}throw error;}
        if(selected){result.then(outcome=>{try{
          if(outcome.kind==='response'&&outcome.status===200&&revValidControl(outcome.body,mode.executionId)){
            if(!revRequestsCancel(outcome.body))revEmit(mode,4,1);
          }
        }catch{revFail();}finally{revOriginalPending--;revPublish(mode,revSealed);revMaybeSeal();}},
          ()=>{revOriginalPending--;revFail();revPublish(mode,revSealed);revMaybeSeal();})
          .catch(()=>{revFail();});}
        return result;};
      """.formatted(JSON.writeValueAsString(root + "reporting/httpClient.js"),
          JSON.writeValueAsString(root + "reporting/reportClient.js"));
}

private static String p4OrdinaryRevocationChild() throws Exception {
  String root = Path.of("../studio-runner/dist").toAbsolutePath().normalize().toUri().toString();
  return p4RevocationScalarSupport(3) + """
      import {validateObserved as revValidateObserved} from %s;
      let revReady=false;
      const revProcess={
        on(event,listener){return Reflect.apply(process.on,process,[event,function(...args){
          const result=Reflect.apply(listener,this,args),mode=revMode();
          if(mode?.active&&mode.path===2&&args[0]?.kind==='stop'){
            try{revValidateObserved('replay-ipc#/definitions/Stop',args[0],128);
              if(!revReady||!revStarted)throw new Error('READY');
              revEmit(mode,6,1,0,0,revRestore());revEmit(mode,5,1,0,4);
            }catch{revFail();}}return result;}]);},
        send(...args){const result=Reflect.apply(process.send,process,args),mode=revMode();
          if(mode?.active&&mode.path===2&&args[0]?.kind==='ready'){
            try{const ready=revValidateObserved('replay-ipc#/definitions/Ready3',args[0],16384);
              if(result!==true||ready.runId!==mode.executionId)throw new Error('BINDING');
              revReady=true;revStarted=true;revEmit(mode,1,1);
            }catch{revFail();}}return result;},
        exit(...args){const mode=revMode();try{
          if(mode?.active&&mode.path===2){revInit(mode);revSealing=true;revSealed=true;revPublish(mode,true);}
        }catch{revFail();}finally{return Reflect.apply(process.exit,process,args);}}
      };
      """.formatted(JSON.writeValueAsString(root + "validator/observedReferencePolicy.js"));

package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.studio.guided.session.GuidedContracts;
import com.fasterxml.jackson.databind.JsonNode;
import java.sql.Timestamp;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/**
 * Joins safe source/admission/execution facts to append-only audit events in caller transactions.
 */
@Component
public final class SecretAuditLifecycle {
  private final JdbcTemplate jdbc;
  private final SecretUseAuditRecorder audit;

  public SecretAuditLifecycle(JdbcTemplate jdbc, SecretUseAuditRecorder audit) {
    this.jdbc = jdbc;
    this.audit = audit;
  }

  public SecretUseAuditRecorder.Release guidedRelease(
      JsonNode session,
      JsonNode action,
      String secretId,
      String version,
      SecretUseAuditRecorder.ResolutionOutcome outcome) {
    JsonNode scope = session.path("scope"), coordinate = action.path("coordinate");
    String id = session.path("sessionId").asText();
    long sequence = nextSequence("session_id", id, secretId, coordinate.path("stepId").asText());
    var identity =
        new SecretUseAuditRecorder.Scope(
            SecretUseAuditRecorder.Path.GUIDED,
            null,
            id,
            action.path("admission").path("admissionId").asText(),
            scope.path("principalId").asText(),
            scope.path("csiId").asText(),
            scope.path("environmentId").asText(),
            UUID.fromString(session.path("testId").asText()),
            secretId,
            id + ":" + action.path("ownerFence").asText(),
            sequence,
            coordinate.path("stepId").asText(),
            coordinate.path("ordinal").asInt(),
            guidedReferenceId(
                id,
                action.path("admission").path("admissionId").asText(),
                secretId,
                coordinate.path("stepId").asText()));
    return audit.recordRelease(identity, version, outcome);
  }

  public void guidedOutcome(JsonNode session, JsonNode action) {
    for (var row :
        jdbc.queryForList(
            ("SELECT * FROM studio_secret_use_audit WHERE session_id=? AND admission_id=? AND decis"
                + "ion_stage='DISPATCH'"),
            session.path("sessionId").asText(),
            action.path("admission").path("admissionId").asText())) {
      String code = action.path("outcomeCode").asText();
      audit.recordUsage(
          release(row),
          code.equals("OK")
              ? SecretUseAuditRecorder.UsageOutcome.USED
              : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
    }
  }

  public void guidedTerminal(JsonNode session) {
    String id = session.path("sessionId").asText();
    for (var row :
        jdbc.queryForList(
            ("SELECT a.*,g.document::text AS action FROM studio_secret_use_audit a JOIN studio_guid"
                + "ed_actions g ON g.session_id=a.session_id AND g.admission_id=a.admission_id WHERE a.s"
                + "ession_id=? AND a.decision_stage='DISPATCH' AND NOT EXISTS(SELECT 1 FROM studio_secre"
                + "t_use_audit u WHERE u.release_id=a.id AND u.row_kind='USAGE')"),
            id)) {
      JsonNode action = new GuidedContracts().parse((String) row.get("action"));
      String code = action.path("outcomeCode").asText();
      SecretUseAuditRecorder.UsageOutcome usage =
          code.equals("OK")
              ? SecretUseAuditRecorder.UsageOutcome.USED
              : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME;
      audit.recordUsage(release(row), usage);
    }
    var manifests =
        jdbc.queryForList(
            "SELECT manifest::text FROM studio_guided_source_manifests WHERE session_id=?",
            String.class,
            id);
    if (manifests.isEmpty()) {
      return;
    }
    JsonNode scope = session.path("scope");
    JsonNode manifest = new GuidedContracts().parse(manifests.getFirst());
    var consumed =
        jdbc.queryForList(
            ("SELECT g.document::text AS action,g.proposal::text AS proposal,m.authored_inputs::tex"
                + "t AS inputs FROM studio_guided_actions g JOIN studio_guided_materializations m ON m.s"
                + "ession_id=g.session_id WHERE g.session_id=? AND (g.document->>'dispatchCount')::integ"
                + "er=1 AND g.proposal->'operation'->>'kind'='fill' AND g.proposal->'operation'->'value'"
                + "->>'kind'='secretRef'"),
            id);
    for (JsonNode reference : manifest.path("configurationReferences")) {
      if (!reference.path("kind").asText().equals("secretRef")) {
        continue;
      }
      String secret = reference.path("referenceName").asText();
      String step = reference.path("stepId").asText();
      String referenceId = reference.path("referenceId").asText();
      if (referenceId.isBlank()) {
        throw new IllegalStateException("Missing source reference identity");
      }
      var matching = new java.util.ArrayList<JsonNode>();
      for (var admission : consumed) {
        JsonNode proposal = new GuidedContracts().parse((String) admission.get("proposal"));
        JsonNode action = new GuidedContracts().parse((String) admission.get("action"));
        for (JsonNode input :
            new GuidedContracts().parse((String) admission.get("inputs")).path("inputs")) {
          if (input
                  .path("inputId")
                  .equals(proposal.path("operation").path("value").path("sourceInputId"))
              && input.path("kind").asText().equals("secretRef")
              && input.path("secretId").asText().equals(secret)
              && input.path("sourceStepId").asText().equals(step)
              && input.path("intendedSlot").asText().equals("fill.value")
              && input.path("provenance").path("referenceId").asText().equals(referenceId)
              && action.path("coordinate").path("stepId").asText().equals(step)) {
            matching.add(action);
          }
        }
      }
      if (matching.isEmpty()) {
        Integer summaries =
            jdbc.queryForObject(
                ("SELECT count(*) FROM studio_secret_use_audit WHERE session_id=? AND source_reference_"
                    + "id=? AND row_kind='USAGE'"),
                Integer.class,
                id,
                referenceId);
        if (summaries != null && summaries > 0) {
          continue;
        }
        audit.recordUnreachedGuided(
            new SecretUseAuditRecorder.Scope(
                SecretUseAuditRecorder.Path.GUIDED,
                null,
                id,
                null,
                scope.path("principalId").asText(),
                scope.path("csiId").asText(),
                scope.path("environmentId").asText(),
                UUID.fromString(session.path("testId").asText()),
                secret,
                id + ":" + session.path("owner").path("fence").asText(),
                null,
                step,
                null,
                referenceId));
      } else {
        for (JsonNode actual : matching) {
          String admissionId = actual.path("admission").path("admissionId").asText();
          Integer existing =
              jdbc.queryForObject(
                  ("SELECT count(*) FROM studio_secret_use_audit WHERE session_id=? AND admission_id=? AN"
                      + "D row_kind='USAGE'"),
                  Integer.class,
                  id,
                  admissionId);
          if (existing != null && existing > 0) {
            continue;
          }
          audit.recordConsumedNoDecision(
              new SecretUseAuditRecorder.Scope(
                  SecretUseAuditRecorder.Path.GUIDED,
                  null,
                  id,
                  admissionId,
                  scope.path("principalId").asText(),
                  scope.path("csiId").asText(),
                  scope.path("environmentId").asText(),
                  UUID.fromString(session.path("testId").asText()),
                  secret,
                  id + ":" + actual.path("ownerFence").asText(),
                  null,
                  actual.path("coordinate").path("stepId").asText(),
                  actual.path("coordinate").path("ordinal").asInt(),
                  referenceId),
              SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
        }
      }
    }
  }

  private String guidedReferenceId(
      String sessionId, String admissionId, String secretId, String stepId) {
    var rows =
        jdbc.queryForList(
            ("SELECT g.proposal::text AS proposal,m.authored_inputs::text AS inputs FROM studio_gui"
                + "ded_actions g JOIN studio_guided_materializations m ON m.session_id=g.session_id WHER"
                + "E g.session_id=? AND g.admission_id=?"),
            sessionId,
            admissionId);
    var ids = new java.util.HashSet<String>();
    for (var row : rows) {
      JsonNode proposal = new GuidedContracts().parse((String) row.get("proposal"));
      for (JsonNode input :
          new GuidedContracts().parse((String) row.get("inputs")).path("inputs")) {
        if (input
                .path("inputId")
                .equals(proposal.path("operation").path("value").path("sourceInputId"))
            && input.path("kind").asText().equals("secretRef")
            && input.path("secretId").asText().equals(secretId)
            && input.path("sourceStepId").asText().equals(stepId)
            && input.path("intendedSlot").asText().equals("fill.value")) {
          ids.add(input.path("provenance").path("referenceId").asText());
        }
      }
    }
    if (ids.size() != 1 || ids.contains("")) {
      throw new IllegalStateException("Missing consumed source reference identity");
    }
    return ids.iterator().next();
  }

  /** Only backend decisions made before a secret frame can enter transport may use this path. */
  public void guidedNoSend(JsonNode session, JsonNode action) {
    for (var row :
        jdbc.queryForList(
            ("SELECT * FROM studio_secret_use_audit WHERE session_id=? AND admission_id=? AND decis"
                + "ion_stage='DISPATCH'"),
            session.path("sessionId").asText(),
            action.path("admission").path("admissionId").asText())) {
      audit.recordUsage(release(row), SecretUseAuditRecorder.UsageOutcome.REFUSED);
    }
  }

  public boolean replayTerminalSettlement(
      UUID execution, String plannedErrorCode, java.time.Instant plannedEndedAt) {
    return audit.recordObservedTerminalSettlement(execution, plannedErrorCode, plannedEndedAt);
  }

  public void replayReadEntry(JsonNode binding, String leaseOwner, String secretId) {
    audit.recordObservedReadEntry(binding, leaseOwner, secretId);
  }

  public void replayNoSendDecision(
      JsonNode binding,
      String leaseOwner,
      java.util.Set<String> notEntered,
      SecretUseAuditRecorder.NoSendDisposition disposition) {
    var proven = new java.util.LinkedHashSet<>(notEntered);
    proven.removeAll(
        jdbc.queryForList(
            "SELECT secret_id FROM studio_observed_secret_read_entries WHERE execution_id=? AND attempt_id=?",
            String.class,
            UUID.fromString(binding.path("executionId").asText()),
            UUID.fromString(binding.path("attemptId").asText())));
    audit.recordObservedNoSend(binding, leaseOwner, proven, disposition);
  }

  /** An authoritative terminal owner cannot infer effects from an absent child report. */
  public void replayOwnerTerminal(UUID execution) {
    replayDecision(execution, null, SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
  }

  /** Called only with actual failed resolution or an authoritative runner no-admission refusal. */
  public void replayNoSend(UUID execution, UUID attempt) {
    replayDecision(execution, attempt, SecretUseAuditRecorder.UsageOutcome.REFUSED);
  }

  private void replayDecision(
      UUID execution, UUID attempt, SecretUseAuditRecorder.UsageOutcome usage) {
    for (var row :
        jdbc.queryForList(
            ("SELECT a.* FROM studio_secret_use_audit a WHERE a.execution_id=? AND (?::text IS NULL"
                + " OR a.attempt_id=?::text) AND a.decision_stage='DISPATCH' AND NOT EXISTS (SELECT 1 FR"
                + "OM studio_secret_use_audit u WHERE u.release_id=a.id AND u.row_kind='USAGE')"),
            execution,
            attempt == null ? null : attempt.toString(),
            attempt == null ? null : attempt.toString())) {
      audit.recordUsage(release(row), usage);
    }
  }

  public void replayRelease(
      JsonNode binding,
      List<String> ids,
      Map<String, String> versions,
      SecretUseAuditRecorder.ResolutionOutcome outcome) {
    UUID execution = UUID.fromString(binding.path("executionId").asText());
    for (String id : ids) {
      audit.recordRelease(
          new SecretUseAuditRecorder.Scope(
              SecretUseAuditRecorder.Path.OBSERVED_REPLAY,
              execution,
              null,
              null,
              binding.path("principalId").asText(),
              binding.path("csiId").asText(),
              binding.path("environment").asText(),
              UUID.fromString(binding.path("testId").asText()),
              id,
              binding.path("attemptId").asText(),
              nextSequence("execution_id", execution, id, null),
              null,
              null),
          versions.get(id),
          outcome);
    }
  }

  public void replayKnownUses(UUID execution, UUID attempt, Map<String, String> usage) {
    if (usage.isEmpty()) {
      return;
    }
    if (usage.values().stream().anyMatch(value -> !"USED".equals(value))) {
      throw new IllegalArgumentException("Invalid positive secret usage report");
    }
    var releases =
        jdbc.queryForList(
            ("SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decis"
                + "ion_stage='DISPATCH' AND outcome='RESOLVED'"),
            execution,
            attempt.toString());
    var available = new java.util.HashSet<String>();
    releases.forEach(row -> available.add((String) row.get("secret_id")));
    if (!available.containsAll(usage.keySet())) {
      throw new IllegalArgumentException("Missing scoped resolved secret release");
    }
    for (var row : releases) {
      if (usage.containsKey((String) row.get("secret_id"))) {
        audit.recordUsage(release(row), SecretUseAuditRecorder.UsageOutcome.USED);
      }
    }
  }

  public void replayTerminal(UUID execution, UUID attempt, Map<String, String> usage) {
    var rows =
        jdbc.queryForList(
            ("SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decis"
                + "ion_stage='DISPATCH'"),
            execution,
            attempt.toString());
    var declared = new java.util.HashSet<String>();
    rows.forEach(row -> declared.add((String) row.get("secret_id")));
    if (!declared.containsAll(usage.keySet())) {
      throw new IllegalArgumentException("Invalid secret usage report");
    }
    for (var row : rows) {
      audit.recordUsage(
          release(row),
          usage.containsKey((String) row.get("secret_id"))
              ? SecretUseAuditRecorder.UsageOutcome.valueOf(
                  usage.get((String) row.get("secret_id")))
              : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
    }
  }

  private long nextSequence(String ownerColumn, Object id, String secret, String step) {
    Long count =
        jdbc.queryForObject(
            "SELECT COALESCE(max(release_seq),0)+1 FROM studio_secret_use_audit WHERE "
                + ownerColumn
                + "=? AND secret_id=? AND coordinate_step_id IS NOT DISTINCT FROM ? AND decision_stage='DISPATCH'",
            Long.class,
            id,
            secret,
            step);
    return count == null ? 1 : count;
  }

  public static SecretUseAuditRecorder.Release release(Map<String, Object> row) {
    var scope =
        new SecretUseAuditRecorder.Scope(
            SecretUseAuditRecorder.Path.valueOf((String) row.get("path")),
            (UUID) row.get("execution_id"),
            (String) row.get("session_id"),
            (String) row.get("admission_id"),
            (String) row.get("principal_id"),
            (String) row.get("csi_id"),
            (String) row.get("environment"),
            (UUID) row.get("test_id"),
            (String) row.get("secret_id"),
            (String) row.get("attempt_id"),
            ((Number) row.get("release_seq")).longValue(),
            (String) row.get("coordinate_step_id"),
            (Integer) row.get("coordinate_ordinal"),
            (String) row.get("source_reference_id"));
    return new SecretUseAuditRecorder.Release(
        (UUID) row.get("id"),
        ((Timestamp) row.get("release_occurred_at")).toInstant(),
        scope,
        (String) row.get("vault_version"),
        SecretUseAuditRecorder.ResolutionOutcome.valueOf((String) row.get("outcome")));
  }
}
